#include "WCP2dToy/TimeKeeper.h"

#include <sstream>
#include <iostream>		// debugging

using namespace std;
using namespace WCP;

/** * @brief Constructor for TimeKeeper class initializing with a message and starting time.
 *
 * This constructor initializes a TimeKeeper object with a specified message and starting timestamp.
 *
 * @param msg The initial message describing the timing event.
 * @param starting_time The starting point in time for the timer.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
TimeKeeper::TimeKeeper(const std::string& msg, ptime starting_time)
{
    //cerr << "TimeKeeper starting with \"" << msg << "\"" << endl;
    m_events.push_back(event(starting_time, msg));
}

TimeKeeper::~TimeKeeper()
{
}

/** * @brief Accepts a timestamped message and stores it as an event.
 *
 * This operator overload method takes a string message and a current timestamp,
 * records them as an event, and then emits the last recorded event.
 *
 * @param msg The message to be logged with the timestamp.
 * @param now The current timestamp.
 * @return A string representation of the emitted event.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
std::string TimeKeeper::operator()(std::string msg, ptime now)
{
    //cerr << "TimeKeeper: accepting message: " << msg << endl;
    m_events.push_back(event(now, msg));
    return emit(-1);
}

/** * @brief Retrieves the start time recorded by the TimeKeeper instance.
 *
 * This function returns the first timestamp stored in the TimeKeeper object,
 * representing the start time of the recording period.
 *
 * @return boost::posix_time::ptime The start time as a posix_time object.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
boost::posix_time::ptime TimeKeeper::start_time() const
{
    return (*this)[0].first;
}
/** * @brief Retrieves the last recorded timestamp.
 *
 * Returns the most recent timestamp stored in the TimeKeeper object.
 *
 * @return boost::posix_time::ptime The last recorded timestamp.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
boost::posix_time::ptime TimeKeeper::last_time() const
{
    return (*this)[-1].first;
}
/** * @brief Returns the duration of the last recorded interval.
 *
 * Calculates the difference between the timestamps of the most recent entry and the second-to-last entry in the TimeKeeper object.
 *
 * @return TimeKeeper::deltat Duration of the last recorded interval.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
TimeKeeper::deltat TimeKeeper::last_duration() const
{
    return (*this)[-1].first - (*this)[-2].first;
}

/** * @brief Calculates the duration since the start time up to the specified current time.
 *
 * This function computes the difference between the provided current time (`now`) and the stored `start_time`.
 *
 * @param now The current point in time.
 * @return boost::posix_time::time_duration The duration elapsed since the start time until the current time.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
boost::posix_time::time_duration TimeKeeper::since(ptime now) const
{
    return now - start_time();
}

/** * @brief Returns the event at the specified index.
 *
 * If the index is negative, it wraps around to the end of the events list.
 *
 * @param ind Index of the event to retrieve.
 * @return Event object at the specified index.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
TimeKeeper::event TimeKeeper::operator[](int ind) const
{
    while (ind < 0) { ind += m_events.size();}

    return m_events[ind];
}

/** * Generates a summary of events stored in the TimeKeeper object.
 *
 * Iterates over each event in m_events, emits a string representation of each event,
 * and appends it to a stringstream. Returns the concatenated string of all emitted events.
 *
 * @return A string containing summaries of all events.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
std::string TimeKeeper::summary() const
{
    stringstream ss;
    for (int ind=0; ind<m_events.size(); ++ind) {
	ss << this->emit(ind) << "\n";
    }
    return ss.str();
}

/** * Emits a formatted string representing the timing information of an event relative to the start and previous events.
 *
 * @param ind Index of the event to emit timing information for.
 * @return Formatted string containing the timing details.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
std::string TimeKeeper::emit(int ind) const
{
    while (ind < 0) { ind += m_events.size();}
    //cerr << "emit " << ind << endl;
    int prev_ind = ind-1;
    if (prev_ind<0) prev_ind=0;
    const event& prev = (*this)[prev_ind];
    const event& evt = (*this)[ind];

    deltat from_start = since(evt.first);
    deltat from_last = evt.first - prev.first;

    stringstream ss;
    ss << "TICK: " << from_start.total_milliseconds() << " ms "
       << "(this: " << from_last.total_milliseconds() << " ms) "
       << evt.second;
    return ss.str();
}
